1	--!
2	--! @author:    N. Selvarajah
3	--! @brief:     Unit tests for the FIFO module.
4	--!
5	--! @license    This project is released under the terms of the MIT License. See LICENSE for more details.
6	--!
7	
8	-- VUnit: run_all_in_same_sim
9	
10	library ieee;
11	use ieee.std_logic_1164.all;
12	use ieee.numeric_std.all;
13	use ieee.math_real.all;
14	
15	library vunit_lib;
16	context vunit_lib.vunit_context;
17	
18	library osvvm;
19	use osvvm.RandomPkg.RandomPType;
20	
21	use work.tb_utils.all;
22	
23	
24	entity tb_fifo_sync is
25	    generic (
26	        runner_cfg: string := runner_cfg_default;
27	        tb_path: string
28	    );
29	end entity;
30	
31	architecture tb of tb_fifo_sync is
32	    -------------------------------------------------------------
33	    -- Internal tb signals/constants
34	    -------------------------------------------------------------
35	    constant PROPAGATION_TIME: time := 1 ns;
36	    constant SIMULATION_TIMEOUT_TIME: time := 1 ms;
37	    constant ENABLE_DEBUG_PRINT: boolean := false;
38	
39	    constant SYS_CLK_FREQUENCY: real := real(100000000); -- 100 MHz
40	    constant SYS_CLK_PHASE: time := 0 fs;
41	
42	    signal sys_clk_enable: std_ulogic := '1';
43	    signal simulation_done: boolean := false;
44	    -------------------------------------------------------------
45	
46	    -------------------------------------------------------------
47	    -- DuT signals, constants
48	    -------------------------------------------------------------
49	    constant FIFO_DEPTH: positive := 1024;
50	    constant DATA_WIDTH: positive := 8;
51	
52	    signal sys_clk: std_ulogic := '0';
53	    signal sys_rst_n: std_ulogic := '1';
54	
55	    signal write_enable: std_ulogic := '0';
56	    signal read_enable: std_ulogic := '0';
57	
58	    signal write_data: std_ulogic_vector(DATA_WIDTH - 1 downto 0) := (others => '0');
59	    signal read_data_xilinx: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
60	    signal read_data_own: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
61	
62	    signal full_xilinx: std_ulogic;
63	    signal full_own: std_ulogic;
64	
65	    signal empty_xilinx: std_ulogic;
66	    signal empty_own: std_ulogic;
67	
68	    signal words_stored_xilinx: natural range 0 to FIFO_DEPTH;
69	    signal words_stored_own: natural range 0 to FIFO_DEPTH;
70	
71	    signal read_data_valid_xilinx: std_ulogic;
72	    signal read_data_valid_own: std_ulogic;
73	    -------------------------------------------------------------
74	begin
75	    ------------------------------------------------------------
76	    -- CLOCK and RESET Generation
77	    ------------------------------------------------------------
78	    sys_clk_enable <= '1';
79	    generate_advanced_clock(sys_clk, SYS_CLK_FREQUENCY, SYS_CLK_PHASE, sys_clk_enable);
80	    ------------------------------------------------------------
81	
82	    ------------------------------------------------------------
83	    -- VUnit
84	    ------------------------------------------------------------
85	    test_runner_watchdog(runner, SIMULATION_TIMEOUT_TIME);
86	
87	    main: process begin
88	        test_runner_setup(runner, runner_cfg);
89	        info("Starting tb_fifo_sync");
90	
91	        if ENABLE_DEBUG_PRINT then
92	            show(display_handler, debug);
93	        end if;
94	
95	        wait until simulation_done;
96	        info("Simulation done, all tests passed!" & LF);
97	
98	        test_runner_cleanup(runner);
99	        wait;
100	    end process;
101	    ------------------------------------------------------------
102	
103	    ------------------------------------------------------------
104	    -- Checker
105	    ------------------------------------------------------------
106	    checker: process
107	        variable random: RandomPType;
108	
109	        procedure wait_sys_clk_cycles(cycles: natural) is begin
110	            for i in 0 to cycles - 1 loop
111	                wait until rising_edge(sys_clk);
112	            end loop;
113	            wait for PROPAGATION_TIME;
114	        end procedure;
115	
116	        procedure restart_module is begin
117	            sys_rst_n <= '0';
118	            wait_sys_clk_cycles(1);
119	            sys_rst_n <= '1';
120	            wait_sys_clk_cycles(1);
121	        end procedure;
122	
123	        procedure check_fifo_status(expected_full, expected_empty: std_ulogic := '-') is begin
124	            if expected_full /= '-' then
125	                -- check_equal(got => full_xilinx, expected => expected_full, msg => "full_xilinx");
126	                check_equal(got => full_own, expected => expected_full, msg => "full_own");
127	            end if;
128	            if expected_empty /= '-' then
129	                -- check_equal(got => empty_xilinx, expected => expected_empty, msg => "empty_xilinx");
130	                check_equal(got => empty_own, expected => expected_empty, msg => "empty_own");
131	            end if;
132	        end procedure;
133	
134	        procedure check_fifo_output(expected_data: std_ulogic_vector) is begin
135	            -- check_equal(got => read_data_xilinx, expected => expected_data, msg => "read_data_xilinx");
136	            check_equal(got => read_data_own, expected => expected_data, msg => "read_data_own");
137	        end procedure;
138	
139	        procedure check_word_count(expected_count: natural) is begin
140	            check_equal(got => words_stored_own, expected => expected_count, msg => "words_stored_own");
141	        end procedure;
142	
143	        procedure test_empty_fifo is begin
144	            info("Test 1.0) test_empty_fifo" & LF);
145	            restart_module;
146	            check_fifo_status(expected_full => '0', expected_empty => '1');
147	
148	            write_enable <= '0';
149	            read_enable <= '1';
150	            wait_sys_clk_cycles(1);
151	            check_fifo_status(expected_full => '0', expected_empty => '1');
152	
153	            write_enable <= '1';
154	            read_enable <= '0';
155	            write_data <= random.RandSlv(write_data'length);
156	            wait_sys_clk_cycles(1);
157	            check_fifo_status(expected_full => '0', expected_empty => '0');
158	
159	            write_enable <= '0';
160	            read_enable <= '1';
161	            wait_sys_clk_cycles(1);
162	            check_fifo_status(expected_full => '0', expected_empty => '1');
163	            check_fifo_output(expected_data => write_data);
164	
165	            wait_sys_clk_cycles(random.RandInt(1, 10));
166	            check_fifo_status(expected_full => '0', expected_empty => '1');
167	            read_enable <= '0';
168	            write_enable <= '0';
169	
170	            wait_sys_clk_cycles(1);
171	            info("Test 1.0) test_empty_fifo completed successfully" & LF);
172	        end procedure;
173	
174	        procedure test_full_fifo is begin
175	            info("Test 2.0) test_full_fifo" & LF);
176	            restart_module;
177	
178	            check_fifo_status(expected_full => '0', expected_empty => '1');
179	
180	            for i in 0 to FIFO_DEPTH - 1 loop
181	                write_enable <= '1';
182	                read_enable <= '0';
183	                write_data <= std_ulogic_vector(to_unsigned(i mod 2**write_data'length, write_data'length));
184	                wait_sys_clk_cycles(1);
185	
186	                if i = FIFO_DEPTH - 1 then
187	                    check_fifo_status(expected_full => '1', expected_empty => '0');
188	                else
189	                    check_fifo_status(expected_full => '0', expected_empty => '0');
190	                end if;
191	            end loop;
192	
193	            for i in 0 to FIFO_DEPTH - 1 loop
194	                write_enable <= '0';
195	                read_enable <= '1';
196	                wait_sys_clk_cycles(1);
197	                -- FIFO reads in FIFO order (first-in, first-out), so we expect the data in write order
198	                check_fifo_output(expected_data => std_ulogic_vector(to_unsigned(i mod 2**write_data'length, write_data'length)));
199	
200	                if i = FIFO_DEPTH - 1 then
201	                    check_fifo_status(expected_full => '0', expected_empty => '1');
202	                else
203	                    check_fifo_status(expected_full => '0', expected_empty => '0');
204	                end if;
205	            end loop;
206	
207	            write_enable <= '0';
208	            read_enable <= '0';
209	            wait_sys_clk_cycles(1);
210	            info("Test 2.0) test_full_fifo completed successfully" & LF);
211	        end procedure;
212	
213	        procedure test_when_write_and_read_requests_are_active is
214	            variable past_data: write_data'subtype;
215	            variable new_data: write_data'subtype;
216	        begin
217	            info("Test 3.0) test_when_write_and_read_requests_are_active" & LF);
218	            restart_module;
219	
220	            check_fifo_status(expected_full => '0', expected_empty => '1');
221	
222	            -- Step 1: Write first item
223	            write_enable <= '1';
224	            read_enable <= '0';
225	            write_data <= random.RandSlv(write_data'length);
226	            wait_sys_clk_cycles(1);
227	            check_fifo_status(expected_full => '0', expected_empty => '0');
228	            past_data := write_data;
229	
230	            -- Step 2: Simultaneous write and read
231	            write_enable <= '1';
232	            read_enable <= '1';
233	            new_data := random.RandSlv(write_data'length);
234	            write_data <= new_data;
235	            wait_sys_clk_cycles(1);
236	            check_fifo_status(expected_full => '0', expected_empty => '0');
237	            check_fifo_output(expected_data => past_data);  -- Should read the first item
238	
239	            -- Step 3: Stop both operations
240	            write_enable <= '0';
241	            read_enable <= '0';
242	            wait_sys_clk_cycles(1);
243	            check_fifo_status(expected_full => '0', expected_empty => '0');
244	            -- Note: not checking read_data here since no read is active
245	
246	            -- Step 4: Read the second item that was written in step 2
247	            read_enable <= '1';
248	            wait_sys_clk_cycles(1);
249	            check_fifo_status(expected_full => '0', expected_empty => '1');  -- Should be empty now
250	            check_fifo_output(expected_data => new_data);
251	
252	            read_enable <= '0';
253	            wait_sys_clk_cycles(1);
254	            info("Test 3.0) test_when_write_and_read_requests_are_active completed successfully" & LF);
255	        end procedure;
256	
257	        procedure test_reset_behavior is begin
258	            info("Test 4.0) test_reset_behavior" & LF);
259	            restart_module;
260	
261	            -- Write some data
262	            for i in 0 to 7 loop
263	                write_enable <= '1';
264	                read_enable <= '0';
265	                write_data <= std_ulogic_vector(to_unsigned(i + 100, write_data'length));
266	                wait_sys_clk_cycles(1);
267	            end loop;
268	            write_enable <= '0';
269	
270	            wait_sys_clk_cycles(2);
271	            check_fifo_status(expected_full => '0', expected_empty => '0');
272	
273	            -- Reset during operation
274	            sys_rst_n <= '0';
275	            wait_sys_clk_cycles(3);
276	            sys_rst_n <= '1';
277	            wait_sys_clk_cycles(2);
278	
279	            -- Verify state after reset
280	            check_fifo_status(expected_full => '0', expected_empty => '1');
281	            check_word_count(expected_count => 0);
282	
283	            -- Verify normal operation after reset
284	            write_enable <= '1';
285	            write_data <= std_ulogic_vector(to_unsigned(42, write_data'length));
286	            wait_sys_clk_cycles(1);
287	            check_fifo_status(expected_full => '0', expected_empty => '0');
288	
289	            write_enable <= '0';
290	            read_enable <= '1';
291	            wait_sys_clk_cycles(1);
292	            check_fifo_output(expected_data => std_ulogic_vector(to_unsigned(42, write_data'length)));
293	            check_fifo_status(expected_full => '0', expected_empty => '1');
294	
295	            read_enable <= '0';
296	            wait_sys_clk_cycles(1);
297	            info("Test 4.0) test_reset_behavior completed successfully" & LF);
298	        end procedure;
299	
300	        procedure test_reset_during_operations is begin
301	            info("Test 5.0) test_reset_during_operations" & LF);
302	
303	            info("Test 5.1) Reset during write operation" & LF);
304	            restart_module;
305	
306	            -- Start a write operation
307	            write_enable <= '1';
308	            write_data <= x"EF";
309	            wait_sys_clk_cycles(1);
310	
311	            -- Assert reset during write
312	            sys_rst_n <= '0';
313	            wait_sys_clk_cycles(1);
314	            write_enable <= '0';
315	            wait_sys_clk_cycles(2);
316	            sys_rst_n <= '1';
317	            wait_sys_clk_cycles(2);
318	
319	            -- Verify FIFO is empty and write was not completed
320	            check_fifo_status(expected_full => '0', expected_empty => '1');
321	
322	            info("Test 5.2) Reset during read operation" & LF);
323	            restart_module;
324	
325	            -- Write some data first
326	            write_enable <= '1';
327	            write_data <= x"AA";
328	            wait_sys_clk_cycles(1);
329	            write_data <= x"BB";
330	            wait_sys_clk_cycles(1);
331	            write_enable <= '0';
332	
333	            -- Start a read operation
334	            read_enable <= '1';
335	            wait_sys_clk_cycles(1);
336	
337	            -- Assert reset during read
338	            sys_rst_n <= '0';
339	            wait_sys_clk_cycles(1);
340	            read_enable <= '0';
341	            wait_sys_clk_cycles(2);
342	            sys_rst_n <= '1';
343	            wait_sys_clk_cycles(2);
344	
345	            -- Verify FIFO is empty and in correct state
346	            check_fifo_status(expected_full => '0', expected_empty => '1');
347	
348	            info("Test 5.0) test_reset_during_operations completed successfully" & LF);
349	        end procedure;
350	
351	        procedure test_word_count_accuracy is begin
352	            info("Test 6.0) test_word_count_accuracy" & LF);
353	            restart_module;
354	
355	            -- Test word count with incremental writes
356	            for i in 0 to 15 loop
357	                write_enable <= '1';
358	                write_data <= std_ulogic_vector(to_unsigned(i, write_data'length));
359	                wait_sys_clk_cycles(1);
360	                write_enable <= '0';
361	                wait_sys_clk_cycles(1);
362	
363	                -- Check that word count is correct
364	                check_equal(got => words_stored_own, expected => i + 1, msg => "Words stored count after " & to_string(i+1) & " writes");
365	            end loop;
366	
367	            -- Test word count with incremental reads
368	            for i in 15 downto 0 loop
369	                read_enable <= '1';
370	                wait_sys_clk_cycles(1);
371	                read_enable <= '0';
372	                wait_sys_clk_cycles(1);
373	
374	                -- Check word count
375	                check_equal(got => words_stored_own, expected => i, msg => "Words stored count after reading, " & to_string(i) & " remaining");
376	
377	                if i = 0 then
378	                    check_fifo_status(expected_full => '0', expected_empty => '1');
379	                else
380	                    check_fifo_status(expected_full => '0', expected_empty => '0');
381	                end if;
382	            end loop;
383	
384	            info("Test 6.0) test_word_count_accuracy completed successfully" & LF);
385	        end procedure;
386	
387	        procedure test_simultaneous_read_write_advanced is begin
388	            info("Test 7.0) test_simultaneous_read_write_advanced" & LF);
389	            restart_module;
390	
391	            -- First fill half the FIFO
392	            for i in 0 to 15 loop
393	                write_enable <= '1';
394	                write_data <= std_ulogic_vector(to_unsigned(i + 200, write_data'length));
395	                wait_sys_clk_cycles(1);
396	            end loop;
397	            write_enable <= '0';
398	            wait_sys_clk_cycles(2);
399	
400	            -- Now perform simultaneous read/write operations
401	            for i in 0 to 7 loop
402	                write_enable <= '1';
403	                read_enable <= '1';
404	                write_data <= std_ulogic_vector(to_unsigned(i + 300, write_data'length));
405	                wait_sys_clk_cycles(1);
406	
407	                -- Check that read data matches expected (FIFO order)
408	                check_fifo_output(expected_data => std_ulogic_vector(to_unsigned(i + 200, write_data'length)));
409	            end loop;
410	
411	            write_enable <= '0';
412	            read_enable <= '0';
413	            wait_sys_clk_cycles(2);
414	
415	            -- Read remaining data
416	            for i in 8 to 15 loop
417	                read_enable <= '1';
418	                wait_sys_clk_cycles(1);
419	                check_fifo_output(expected_data => std_ulogic_vector(to_unsigned(i + 200, write_data'length)));
420	            end loop;
421	
422	            -- Read the new data that was written during simultaneous operation
423	            for i in 0 to 7 loop
424	                wait_sys_clk_cycles(1);
425	                check_fifo_output(expected_data => std_ulogic_vector(to_unsigned(i + 300, write_data'length)));
426	            end loop;
427	
428	            read_enable <= '0';
429	            wait_sys_clk_cycles(1);
430	            check_fifo_status(expected_full => '0', expected_empty => '1');
431	
432	            info("Test 7.0) test_simultaneous_read_write_advanced completed successfully" & LF);
433	        end procedure;
434	
435	        procedure test_edge_cases is begin
436	            info("Test 8.0) test_edge_cases" & LF);
437	            restart_module;
438	
439	            info("Test 8.1) Write when full (should be ignored)" & LF);
440	            -- Fill FIFO completely
441	            for i in 0 to FIFO_DEPTH - 1 loop
442	                write_enable <= '1';
443	                write_data <= std_ulogic_vector(to_unsigned(i mod 256, write_data'length));
444	                wait_sys_clk_cycles(1);
445	            end loop;
446	            write_enable <= '0';
447	            wait_sys_clk_cycles(1);
448	            check_fifo_status(expected_full => '1', expected_empty => '0');
449	
450	            -- Try to write when full (should be ignored)
451	            write_enable <= '1';
452	            write_data <= x"FF";
453	            wait_sys_clk_cycles(3);
454	            write_enable <= '0';
455	            check_fifo_status(expected_full => '1', expected_empty => '0');
456	
457	            info("Test 8.2) Read when empty (should be ignored)" & LF);
458	            -- Empty the FIFO
459	            for i in 0 to FIFO_DEPTH - 1 loop
460	                read_enable <= '1';
461	                wait_sys_clk_cycles(1);
462	            end loop;
463	            read_enable <= '0';
464	            wait_sys_clk_cycles(1);
465	            check_fifo_status(expected_full => '0', expected_empty => '1');
466	
467	            -- Try to read when empty (should be ignored)
468	            read_enable <= '1';
469	            wait_sys_clk_cycles(3);
470	            read_enable <= '0';
471	            check_fifo_status(expected_full => '0', expected_empty => '1');
472	
473	            info("Test 8.0) test_edge_cases completed successfully" & LF);
474	        end procedure;
475	
476	        procedure test_stress_operations is
477	            variable num_writes: natural;
478	        begin
479	            info("Test 9.0) test_stress_operations" & LF);
480	            restart_module;
481	
482	            -- Stress test with rapid write/read cycles
483	            info("Test 9.1) Rapid write/read cycles" & LF);
484	            for cycle in 0 to 9 loop
485	                -- Rapid writes
486	                for i in 0 to 31 loop
487	                    write_enable <= '1';
488	                    write_data <= std_ulogic_vector(to_unsigned((cycle * 32 + i) mod 256, write_data'length));
489	                    wait_sys_clk_cycles(1);
490	                end loop;
491	                write_enable <= '0';
492	
493	                -- Rapid reads
494	                for i in 0 to 31 loop
495	                    read_enable <= '1';
496	                    wait_sys_clk_cycles(1);
497	                    check_fifo_output(expected_data => std_ulogic_vector(to_unsigned((cycle * 32 + i) mod 256, write_data'length)));
498	                end loop;
499	                read_enable <= '0';
500	                wait_sys_clk_cycles(1);
501	
502	                check_fifo_status(expected_full => '0', expected_empty => '1');
503	            end loop;
504	
505	            info("Test 9.2) Random write/read patterns" & LF);
506	            for cycle in 0 to 4 loop
507	                -- Random number of writes (1 - 10)
508	                num_writes := random.RandInt(1, 10);
509	
510	                for i in 0 to num_writes - 1 loop
511	                    write_enable <= '1';
512	                    write_data <= random.RandSlv(write_data'length);
513	                    wait_sys_clk_cycles(1);
514	                end loop;
515	                write_enable <= '0';
516	
517	                -- Random delay
518	                wait_sys_clk_cycles(random.RandInt(1, 3));
519	
520	                -- Read same number of items
521	                for i in 0 to num_writes - 1 loop
522	                    read_enable <= '1';
523	                    wait_sys_clk_cycles(1);
524	                end loop;
525	                read_enable <= '0';
526	
527	                wait_sys_clk_cycles(1);
528	            end loop;
529	
530	            check_fifo_status(expected_full => '0', expected_empty => '1');
531	            info("Test 9.0) test_stress_operations completed successfully" & LF);
532	        end procedure;
533	    begin
534	        random.InitSeed(tb_path & random'instance_name);
535	
536	        -- Don't remove, else VUnit will not run the test suite
537	        wait_sys_clk_cycles(1);
538	
539	        while test_suite loop
540	            if run("test_empty_fifo") then
541	                test_empty_fifo;
542	            elsif run("test_full_fifo") then
543	                test_full_fifo;
544	            elsif run("test_when_write_and_read_requests_are_active") then
545	                test_when_write_and_read_requests_are_active;
546	            elsif run("test_reset_behavior") then
547	                test_reset_behavior;
548	            elsif run("test_reset_during_operations") then
549	                test_reset_during_operations;
550	            elsif run("test_word_count_accuracy") then
551	                test_word_count_accuracy;
552	            elsif run("test_simultaneous_read_write_advanced") then
553	                test_simultaneous_read_write_advanced;
554	            elsif run("test_edge_cases") then
555	                test_edge_cases;
556	            elsif run("test_stress_operations") then
557	                test_stress_operations;
558	            else
559	                assert false report "No test has been run!" severity failure;
560	            end if;
561	        end loop;
562	
563	        simulation_done <= true;
564	    end process;
565	    ------------------------------------------------------------
566	
567	    ------------------------------------------------------------
568	    -- Instantiate the DuT
569	    ------------------------------------------------------------
570	    DuT_xilinx: entity work.fifo_sync(xilinx_behavioural_sync_fifo)
571	        generic map (
572	            FIFO_DEPTH => FIFO_DEPTH
573	        )
574	        port map (
575	            sys_clk => sys_clk,
576	            sys_rst_n => sys_rst_n,
577	            write_enable => write_enable,
578	            write_data => write_data,
579	            read_enable => read_enable,
580	            read_data => read_data_xilinx,
581	            read_data_valid => read_data_valid_xilinx,
582	            full => full_xilinx,
583	            empty => empty_xilinx,
584	            words_stored => words_stored_xilinx
585	        );
586	
587	    DuT_own: entity work.fifo_sync(own_behavioural_sync_fifo)
588	        generic map (
589	            FIFO_DEPTH => FIFO_DEPTH
590	        )
591	        port map (
592	            sys_clk => sys_clk,
593	            sys_rst_n => sys_rst_n,
594	            write_enable => write_enable,
595	            write_data => write_data,
596	            read_enable => read_enable,
597	            read_data => read_data_own,
598	            read_data_valid => read_data_valid_own,
599	            full => full_own,
600	            empty => empty_own,
601	            words_stored => words_stored_own
602	        );
603	    ------------------------------------------------------------
604	end architecture;
605

